import { describe, expect, it, vi } from 'vitest';
import { IgdbClient, IgdbGame, igdbYear } from '../src/api/igdb';
import type { HttpRequest } from '../src/api/types';
import details from './fixtures/igdb_game_details.json';
import search from './fixtures/igdb_game_search.json';
import token from './fixtures/igdb_oauth_token.json';

// Generated by the Python CLI's IGDBClient from the same data.
const CLI_ELDEN_RING_NOTE =
	'---\ncollection: "[[Games]]"\ntags:\n  - single-player\n  - multiplayer\n  - rpg\n  - adventure\n---\n\n## Links\nhttps://www.igdb.com/games/elden-ring\n\n## Description\nA new fantasy action RPG. Arise, Tarnished, and be guided by grace to brandish the power of the Elden Ring. Developed by [[FromSoftware]]. Published by [[Bandai Namco Entertainment]].\n';
const CLI_TBD_NOTE =
	'---\ncollection: "[[Games]]"\ntags:\n  - co-op\n---\n\n## Links\nNot available\n\n## Description\nNo description available. Developed by [[Team Cherry]]. Published by [[Team Cherry]].\n';
const TBD_GAME: IgdbGame = {
	id: 1,
	name: 'Hollow Knight: Silksong',
	game_modes: [{ name: 'Co-operative' }, { name: 'Massively Multiplayer Online (MMO)' }],
	involved_companies: [{ company: { name: 'Team Cherry' }, developer: true, publisher: true }],
};

/** Fake HTTP: the Twitch token first, then the given IGDB responses in order. */
function fakeHttp(...responses: unknown[]) {
	const request = vi.fn<(req: HttpRequest) => Promise<unknown>>();
	request.mockResolvedValueOnce(token);
	for (const r of responses) request.mockResolvedValueOnce(r);
	return request;
}

describe('igdbYear', () => {
	it('uses UTC, so a New Year timestamp does not shift with the time zone', () => {
		expect(igdbYear(1704067200)).toBe('2024'); // 2024-01-01T00:00:00Z
		expect(igdbYear(1704067199)).toBe('2023'); // one second earlier
		expect(igdbYear(undefined)).toBeNull();
	});
});

describe('IgdbClient', () => {
	it('signs in through Twitch, then searches with the token', async () => {
		const request = fakeHttp(search);
		const client = new IgdbClient('CID', 'SECRET', request);
		const results = await client.search('Elden "Ring"');

		const tokenUrl = new URL(request.mock.calls[0]?.[0].url ?? '');
		expect(tokenUrl.origin + tokenUrl.pathname).toBe('https://id.twitch.tv/oauth2/token');
		expect(Object.fromEntries(tokenUrl.searchParams)).toEqual({
			client_id: 'CID',
			client_secret: 'SECRET',
			grant_type: 'client_credentials',
		});
		expect(request.mock.calls[0]?.[0].method).toBe('POST');

		const call = request.mock.calls[1]?.[0];
		expect(call?.url).toBe('https://api.igdb.com/v4/games');
		expect(call?.headers).toMatchObject({
			'Client-ID': 'CID',
			Authorization: 'Bearer test_access_token_12345',
		});
		expect(call?.body).toContain('search "Elden \\"Ring\\"";');
		expect(call?.body).toContain('limit 25;');

		expect(results).toEqual([
			{
				id: '119277',
				title: 'Elden Ring',
				year: '2022',
				overview: 'A new fantasy action RPG...',
				thumbnailUrl: 'https://images.igdb.com/igdb/image/upload/t_thumb/co4thl.jpg',
			},
			{
				id: '234567',
				title: 'Elden Ring: Shadow of the Erdtree',
				year: '2024',
				overview: 'DLC for Elden Ring',
				thumbnailUrl: 'https://images.igdb.com/igdb/image/upload/t_thumb/co5xyz.jpg',
			},
		]);
	});

	it('reuses the token across requests', async () => {
		const request = fakeHttp(search, details);
		const client = new IgdbClient('CID', 'SECRET', request);
		await client.search('Elden Ring');
		await client.getDetails('119277');
		expect(request).toHaveBeenCalledTimes(3);
		expect(request.mock.calls[2]?.[0].body).toContain('where id = 119277;');
	});

	it('fails clearly when Twitch returns no token', async () => {
		const request = vi.fn().mockResolvedValue({});
		await expect(new IgdbClient('a', 'b', request).search('x')).rejects.toThrow('access token');
	});

	it('rejects a missing game and a non-numeric id', async () => {
		const client = new IgdbClient('a', 'b', fakeHttp([]));
		await expect(client.getDetails('5')).rejects.toThrow('not found');
		await expect(client.getDetails('5; fields *')).rejects.toThrow('Invalid IGDB id');
	});

	it('marks a game with no release date by a null year', async () => {
		const client = new IgdbClient('a', 'b', fakeHttp([{ id: 9, name: 'Silksong' }]));
		expect((await client.search('Silksong'))[0]?.year).toBeNull();
	});

	const client = new IgdbClient('a', 'b', vi.fn());
	const game = details[0] as IgdbGame;

	it('matches the CLI note', () => {
		expect(client.formatNote(game)).toBe(CLI_ELDEN_RING_NOTE);
		expect(client.formatNote(TBD_GAME)).toBe(CLI_TBD_NOTE);
	});

	it('matches the CLI filenames, with TBD for unreleased games', () => {
		expect(client.getFilename(game)).toBe('Elden Ring (2022).md');
		expect(client.getFilename(TBD_GAME)).toBe('Hollow Knight - Silksong (TBD).md');
	});

	it('adds the poster', () => {
		expect(client.formatNote(game, 'Elden Ring (2022).jpg')).toContain(
			'poster: "[[Elden Ring (2022).jpg]]"\n---\n\n![[Elden Ring (2022).jpg]]\n\n## Links',
		);
	});

	it('builds the cover URL', () => {
		expect(client.getPosterUrl(game)).toBe(
			'https://images.igdb.com/igdb/image/upload/t_cover_big/co4thl.jpg',
		);
		expect(client.getPosterUrl(TBD_GAME)).toBeNull();
		expect(client.getPosterUrl({ id: 1, cover: null })).toBeNull();
	});

	it('reports title and year', () => {
		expect(client.getTitleAndYear(game)).toEqual({ title: 'Elden Ring', year: '2022' });
		expect(client.getTitleAndYear(TBD_GAME)).toEqual({ title: 'Hollow Knight: Silksong', year: null });
	});
});
